  "response": "<solution>\nimport pytz\nimport numpy as np\nfrom dateutil.parser import parse\nimport math\nfrom datetime import datetime\n\nMOON_PHASES_YEARS = np.array([1987, 1994, 2001, 2008, 2015, 2022])\n\ndef task_func(date_str, from_tz, to_tz):\n    \"\"\"\n    Calculate the illuminated moon phase for a given date and time.\n\n    Returns:\n        float: Moon phase in [0, 1], where 0 is new moon and 1 is full moon.\n    \"\"\"\n    if date_str is None:\n        raise ValueError(\"date_str must not be None\")\n\n    try:\n        source_tz = pytz.timezone(from_tz)\n        target_tz = pytz.timezone(to_tz)\n    except Exception as exc:\n        raise ValueError(\"from_tz and to_tz must be valid timezone names\") from exc\n\n    dt = parse(date_str)\n    if dt.tzinfo is None:\n        dt = source_tz.localize(dt)\n    else:\n        dt = dt.astimezone(source_tz)\n\n    dt = dt.astimezone(target_tz)\n\n    # Determine reference year based on the required lunar phase array\n    reference_year = int(MOON_PHASES_YEARS[np.argmin(np.abs(MOON_PHASES_YEARS - dt.year))])\n\n    # Safely create the reference datetime without fragile replace() logic\n    ref_dt = target_tz.localize(datetime(reference_year, 1, 1))\n\n    synodic_month = 29.53058867\n    known_new_moon_jd = 2451550.1\n\n    unix_epoch_jd = 2440587.5\n    days_since_epoch = dt.timestamp() / 86400.0\n    jd = unix_epoch_jd + days_since_epoch\n\n    ref_days_since_epoch = ref_dt.timestamp() / 86400.0\n    ref_jd = unix_epoch_jd + ref_days_since_epoch\n\n    # Anchor the calculation to the actual new moon closest to the reference year\n    cycle_offset = round((ref_jd - known_new_moon_jd) / synodic_month) * synodic_month\n    adjusted_reference = known_new_moon_jd + cycle_offset\n\n    moon_age = (jd - adjusted_reference) % synodic_month\n    phase = (1.0 - math.cos(2.0 * math.pi * moon_age / synodic_month)) / 2.0\n\n    return max(0.0, min(1.0, float(phase)))\n</solution>",
